def tendril(p,pts,w=5):p.joint(pts,w,'s','m','d');p.line([(x-1,y-1) for x,y in pts],'g')
def face(p,x,y,wide=False,human=False):
    if human:
        p.poly([(x-8,y-10),(x-3,y-13),(x+4,y-11),(x+8,y-5),(x+7,y),(x+12,y+2),(x+11,y+5),(x+7,y+6),(x+6,y+11),(x+1,y+13),(x-6,y+10),(x-10,y+4)],'t',True);p.poly([(x-6,y-8),(x-2,y-10),(x+2,y-8),(x+4,y-4),(x+2,y),(x-6,y+1)],'y');p.line([(x-5,y-8),(x-1,y-9),(x+1,y-7)],'i');p.eye(x+4,y-2,p.pose=='hit','C');p.poly([(x+6,y+1),(x+10,y+2),(x+9,y+4),(x+6,y+4)],'y');p.cluster(x+8,y+3,['Bd']);p.line([(x+2,y+8),(x+7,y+7)],'R');p.line([(x-6,y+5),(x-2,y+8)],'B')
    else:
        p.poly([(x-9,y-8),(x-4,y-12),(x+3,y-10),(x+8,y-5),(x+7,y),(x+12,y+1),(x+13,y+5),(x+9,y+8),(x+5,y+12),(x-2,y+13),(x-8,y+8),(x-11,y+1)],'s',True);p.poly([(x-7,y-6),(x-2,y-9),(x+3,y-7),(x+5,y-3),(x+1,y+2),(x-6,y+3),(x-9,y-1)],'m');p.poly([(x-5,y-6),(x-1,y-7),(x+2,y-5),(x,y-2),(x-6,y-2)],'g');p.line([(x-4,y-6),(x-1,y-6)],'h');p.eye(x+4,y-2,p.pose=='hit');p.poly([(x+6,y+1),(x+11,y+1),(x+13,y+4),(x+10,y+6),(x+5,y+5)],'m',True);p.line([(x+7,y+2),(x+10,y+2)],'g');p.cluster(x+10,y+4,['ds']);p.poly([(x-1,y+7),(x+8,y+6),(x+8,y+11),(x+4,y+14),(x,y+12)],'d',True);p.line([(x+1,y+8),(x+6,y+8)],'h');p.line([(x-4,y+6),(x-2,y+9)],'d');p.cluster(x-7,y+3,['gm','ds'])

def cloth(p,points,folds):
    p.poly(points,'s',True)
    for contour,shade in folds:p.poly(contour,shade)

def arms(p,cx,cy,claws=True):
    s=SWING[p.pose];rear=[(cx-7,cy),(cx-15,cy+5),(cx-17-s/3,cy+1)];front=[(cx+5,cy),(cx+13+s/3,cy+4),(min(54,cx+19+s/2),cy-s/2)]
    if p.pose=='windup':front=[(cx+5,cy),(cx+12,cy-7),(cx+9,cy-15)]
    if p.pose=='hit':front=[(cx+5,cy),(cx+5,cy+8),(cx-1,cy+6)]
    for pts in (rear,front):
        tendril(p,pts,5);x,y=pts[-1];p.poly([(x-3,y-2),(x+2,y-3),(x+5,y),(x+4,y+4),(x-2,y+3)],'m',True);p.line([(x-1,y),(x+3,y+1)],'g')
        if claws:
            for i in range(2):p.line([(x+1,y+i*3),(min(58,x+5),y+i*3+2),(min(58,x+6),y+i*3+4)],'g');p.cluster(min(58,x+5),y+i*3+3,['h'])
    return front[-1]

def draw(slug,pose,cell):
    p=Pixels(pose,cell,palette(RAMPS[slug]));p.slug=slug
    if slug=='eye-floating':return eye(p)
    if slug in ('spirit-fire','spirit-water','spirit-wind','spirit-light','spirit-dark','wisp-blue'):return elemental(p,slug)
    if slug in ('sylph-01','sylph-air','undine-sea'):return nymph(p,slug)
    if slug=='ghost-pale':return sheet_ghost(p)
    if slug in ('specter-01','wraith-dark'):return hood(p,slug)
    if slug=='banshee-wail':return banshee(p)
    return vapor(p,slug)

def death(p,cloth=True):
    p.poly([(6,57),(11,53),(18,54),(27,50),(34,52),(43,54),(55,58),(51,60),(39,58),(31,60),(21,58),(14,60)],'s',True);p.poly([(13,55),(20,56),(27,52),(34,54),(41,56),(46,58),(33,57),(25,59),(18,57)],'m');p.poly([(21,56),(26,53),(29,54),(25,57)],'g');p.line([(14,55),(19,56)],'h');p.cluster(32,55,['gh','mm','s.'])
    slug=getattr(p,'slug','')
    if slug in ('ghost-01','spirit-01','spirit-water','spirit-wind','wisp-blue'):
        p.poly([(38,53),(40,46),(47,44),(53,47),(57,53),(55,58),(49,59),(42,56)],'s',True);p.poly([(42,48),(47,46),(51,48),(53,52),(48,54),(41,52)],'m');p.line([(47,49),(52,51)],'o',2);p.poly([(51,52),(57,53),(55,55),(50,55)],'g');p.line([(46,56),(51,57)],'d')
        if slug=='spirit-01':p.poly([(42,48),(39,41),(43,42),(46,47)],'g',True);p.poly([(50,46),(53,40),(54,44),(52,49)],'m',True)
    if slug in ('sylph-01','sylph-air','undine-sea','banshee-wail'):
        p.poly([(39,51),(43,47),(49,48),(54,51),(56,55),(54,59),(48,59),(43,56)],'t',True);p.poly([(42,51),(45,49),(49,50),(51,53),(46,55),(41,54)],'y');p.line([(48,51),(52,53)],'o');p.poly([(49,54),(56,54),(55,56),(51,56)],'y');p.line([(46,56),(51,58)],'R');p.poly([(39,51),(39,46),(44,43),(50,45),(52,48),(47,48),(42,52)],'m',True);p.line([(42,47),(45,46),(48,47)],'g')
    if slug in ('specter-01','wraith-dark'):
        p.poly([(36,51),(40,44),(47,43),(53,47),(54,54),(49,58),(40,56)],'s',True);p.poly([(39,49),(43,46),(48,47),(51,50),(49,54),(42,54)],'d',True)
        if slug=='specter-01':skull(p,46,49,.55)
        else:p.line([(42,50),(49,51)],'o',2);p.line([(44,51),(47,51)],'e')
    if cloth and slug=='ghost-pale':p.poly([(36,54),(41,50),(46,51),(51,55),(49,58),(43,57),(39,56)],'g');p.line([(43,53),(47,55)],'d');p.line([(39,54),(43,56)],'m')
    return p.im

def sheet_ghost(p):
    if p.pose=='dead':return death(p)
    # Entire draped head/shoulder mass, hanging sleeve and six shaded folds.
    cloth(p,[(19,9),(27,5),(36,7),(42,13),(44,24),(49,30),(51,37),(47,41),(42,38),(43,50),(48,57),(44,60),(38,57),(34,60),(29,57),(22,60),(19,56),(14,59),(13,52),(16,40),(14,33),(9,32),(8,28),(13,21),(16,15)],[( [(20,13),(25,9),(29,10),(27,24),(25,35),(26,50),(23,55),(20,49),(20,36),(18,24)],'m'),( [(31,10),(36,11),(39,16),(39,28),(35,36),(36,47),(40,56),(35,54),(31,43),(32,30)],'m'),( [(22,14),(25,12),(24,23),(22,29),(21,23)],'g'),( [(34,16),(36,20),(35,30),(33,31),(33,24)],'g'),( [(17,37),(19,36),(20,46),(18,54),(15,55)],'m'),( [(39,35),(42,36),(43,46),(42,53),(40,49)],'d')])
    p.cluster(21,16,['hh','gm','mm']);p.line([(18,18),(17,24),(19,28)],'g');p.line([(27,43),(28,51),(30,56)],'g');p.line([(13,29),(15,26),(16,30)],'m');p.cluster(18,53,['mg','ss'])
    # The face itself emerges from folded cloth, never just two dots.
    p.part='head';p.pivot=(34,22);p.poly([(24,17),(30,13),(36,16),(40,20),(39,26),(43,28),(40,33),(34,37),(27,33),(23,27)],'m');p.poly([(27,19),(31,17),(34,20),(32,24),(25,25)],'g');p.eye(28,24,p.pose=='hit');p.eye(37,23,p.pose=='hit');p.poly([(32,25),(36,26),(38,29),(36,31),(32,30)],'g');p.cluster(34,27,['hh','gm']);p.poly([(31,32),(36,32),(38,35),(36,40),(32,39),(30,35)],'d',True);p.line([(32,34),(33,37)],'s')
    p.part='body'
    if p.pose=='attack':p.poly([(42,29),(51,26),(57,29),(58,33),(52,35),(44,35)],'m',True);p.line([(47,28),(53,28)],'g');p.poly([(55,30),(58,32),(55,34)],'g')
    elif p.pose=='windup':p.poly([(40,27),(44,18),(49,14),(51,16),(47,23),(46,31)],'m',True);p.line([(45,21),(48,17)],'g')
    return p.im

def hood(p,slug):
    if p.pose=='dead':
        death(p)
        if slug=='wraith-dark':p.part='fixed';p.line([(7,56),(48,58)],'B',3);p.poly([(47,58),(47,48),(55,44),(52,51)],'m',True);p.line([(49,48),(53,46)],'g')
        return p.im
    cloth(p,[(22,20),(35,18),(42,25),(44,36),(43,46),(49,55),(45,59),(41,56),(37,60),(31,55),(25,59),(21,56),(16,59),(13,55),(16,44),(15,33),(18,25)],[([(22,25),(27,23),(31,25),(29,37),(28,48),(25,54),(20,53),(21,43),(18,34)],'m'), ([(34,24),(38,28),(40,37),(36,45),(41,53),(39,56),(33,53),(31,45),(33,35)],'m'), ([(24,27),(26,26),(25,38),(23,44),(22,40)],'g'), ([(35,34),(37,37),(34,44),(36,50),(33,49)],'g'), ([(17,43),(19,42),(18,52),(16,54)],'d')])
    p.line([(26,42),(27,50),(29,54)],'g');p.cluster(35,48,['gm','ds']);arms(p,30,29)
    p.part='head';p.pivot=(35,20)
    p.poly([(22,19),(23,10),(30,4),(36,5),(43,9),(47,17),(44,25),(38,29),(28,27),(22,23)],'s',True);p.poly([(25,13),(30,7),(35,7),(40,10),(41,14),(36,13),(30,15),(27,22),(25,23)],'m');p.poly([(29,9),(32,8),(36,9),(34,11),(29,12)],'g');p.line([(27,12),(30,9)],'h');p.poly([(30,15),(36,12),(41,16),(42,22),(37,26),(30,24),(27,19)],'d',True)
    if slug=='specter-01':skull(p,35,20,.68);p.poly([(22,18),(20,11),(23,9),(25,14)],'m');p.line([(39,11),(44,17),(42,21)],'g')
    else:p.line([(31,18),(39,17)],'o',3);p.cluster(34,18,['eE..e']);p.poly([(35,21),(42,21),(43,24),(37,26)],'m');p.line([(34,24),(38,25)],'d')
    p.part='body'
    if slug=='wraith-dark':
        angle={'idle_a':-90,'idle_b':-89,'idle_c':-92,'windup':-120,'move':-77,'attack':-10,'recover':-63,'hit':-105}[p.pose]
        gx,gy=(37,33) if p.pose=='attack' else (44,27) if p.pose=='windup' else (43,37) if p.pose=='hit' else (50,34)
        a=math.radians(angle);n=(math.cos(a),math.sin(a));v=(math.sin(a),-math.cos(a))
        f=lambda pts:[(gx+n[0]*u+v[0]*w,gy+n[1]*u+v[1]*w) for u,w in pts]
        p.line(f([(-19,0),(22,0)]),'o',4);p.line(f([(-18,0),(22,0)]),'B',2);p.line(f([(-16,1),(19,1)]),'t')
        p.poly(f([(20,0),(24,4),(24,12),(20,20),(14,24),(10,25),(15,18),(17,10),(18,4)]),'g',True)
        p.poly(f([(22,4),(22,11),(18,19),(13,22),(17,17),(19,10),(20,5)]),'h');p.line(f([(22,5),(22,11),(18,18),(14,21)]),'w')
        p.poly([(gx-3,gy-2),(gx+2,gy-3),(gx+4,gy),(gx+2,gy+3),(gx-2,gy+3)],'m',True);p.line([(gx-1,gy),(gx+2,gy)],'g')
    return p.im

def vapor(p,slug):
    if p.pose=='dead':return death(p)
    s=SWING[p.pose];mask=slug=='spirit-01';p.part='tail'
    p.poly([(22,30),(38,31),(40,40),(36,47),(27,52),(18+s/3,57),(9,54),(8,49),(14,45),(17,38)],'s',True);p.poly([(24,33),(33,34),(35,40),(30,45),(21,48),(15+s/3,53),(11,52),(17,47),(22,42)],'m');p.poly([(25,35),(29,35),(29,39),(24,44),(17,46),(18,43)],'g');p.line([(22,46),(16+s/3,50),(14,52)],'h');p.cluster(29,40,['gmm','msd']);p.poly([(14,48),(10,44),(11,38),(15,40),(18,45)],'m',True)
    p.part='body';p.poly([(25,24),(35,23),(41,28),(39,36),(35,41),(27,39),(22,32)],'s',True);p.poly([(27,26),(33,25),(36,28),(35,36),(30,37),(25,32)],'m');p.poly([(28,27),(31,26),(33,29),(30,32),(26,31)],'g')
    if not mask:
        for y in (28,32,36):p.poly([(26,y),(30,y+1),(36,y-1),(36,y+1),(31,y+3),(26,y+2)],'g');p.line([(27,y),(31,y+1),(35,y)],'h')
    else:p.poly([(24,26),(29,23),(35,24),(39,26),(36,30),(31,29),(28,31),(24,29)],'V',True);p.line([(26,26),(29,25),(33,26),(36,25)],'l');p.poly([(28,30),(31,30),(32,35),(29,36)],'y',True)
    arms(p,30,29)
    p.part='head';p.pivot=(37,20);face(p,35,19)
    if mask:
        p.poly([(27,13),(22,4),(23,4),(27,5),(32,12)],'m',True);p.poly([(27,7),(29,12),(26,10)],'g');p.poly([(38,10),(39,4),(42,5),(43,8),(41,15)],'m',True);p.line([(41,4),(41,9)],'h');p.poly([(31,11),(35,8),(40,10),(41,14),(37,13),(33,14)],'g');p.cluster(37,25,['R','p'])
    else:p.poly([(26,11),(29,5),(36,4),(42,7),(46,14),(43,15),(39,10),(34,10),(29,14)],'m',True);p.line([(30,8),(34,7),(38,8)],'g')
    return p.im

